1	/** Author/assignee escalations for issues and comments. */
2	import { describe, expect, it } from "vitest";
3	import { PermissionDeniedError, assertCan, can, explain } from "@/lib/permissions";
4	import type { CommentId, IssueId, MemberId, ProjectId } from "@/types/common";
5	import type { PermissionResource } from "@/types/permission";
6	import { ALICE, BOB, ORG_A, makeActor } from "../helpers/factories";
7	
8	const PROJECT = "01HZZZPPPPPPPPPPPPPPPPPPPP" as ProjectId;
9	
10	function issue(
11	  authorId = BOB,
12	  assigneeId: typeof ALICE | typeof BOB | null = null,
13	): PermissionResource {
14	  return {
15	    kind: "issue",
16	    orgId: ORG_A,
17	    projectId: PROJECT,
18	    issueId: "01HZZZSSSSSSSSSSSSSSSSSSSS" as IssueId,
19	    authorId,
20	    assigneeId,
21	  };
22	}
23	
24	function comment(authorId = BOB): PermissionResource {
25	  return {
26	    kind: "comment",
27	    orgId: ORG_A,
28	    commentId: "01HZZZCCCCCCCCCCCCCCCCCCCC" as CommentId,
29	    authorId,
30	  };
31	}
32	
33	const viewer = makeActor({ role: "viewer", userId: ALICE });
34	
35	describe("permissions ownership escalations", () => {
36	  it("lets an author update their own issue despite lacking the role", () => {
37	    expect(can(viewer, "issue:update", issue(BOB))).toBe(false);
38	    expect(can(viewer, "issue:update", issue(ALICE))).toBe(true);
39	    expect(explain(viewer, "issue:update", issue(ALICE)).reason).toBe(
40	      "granted_by_ownership",
41	    );
42	  });
43	
44	  it("lets the assignee update and archive an issue they did not author", () => {
45	    expect(can(viewer, "issue:update", issue(BOB, ALICE))).toBe(true);
46	    expect(can(viewer, "issue:archive", issue(BOB, ALICE))).toBe(true);
47	  });
