import type {
  CommentId,
  IssueId,
  MemberId,
  OrgId,
  ProjectId,
  UserId,
  WebhookId,
} from "./common";
import type { Role } from "./member";
import type { ProjectVisibility } from "./project";

/**
 * The complete action vocabulary of `can()`. Every authorization decision in
 * Taskflow names one of these — there is no free-form string permission.
 */
export type PermissionAction =
  | "org:read"
  | "org:update"
  | "org:delete"
  | "org:manage_billing"
  | "org:manage_flags"
  | "member:read"
  | "member:invite"
  | "member:update_role"
  | "member:remove"
  | "project:create"
  | "project:read"
  | "project:update"
  | "project:archive"
  | "project:delete"
  | "issue:create"
  | "issue:read"
  | "issue:update"
  | "issue:assign"
  | "issue:archive"
  | "issue:delete"
  | "comment:create"
  | "comment:read"
  | "comment:update"
  | "comment:delete"
  | "activity:read"
  | "activity:export"
  | "notification:read"
  | "notification:manage"
  | "webhook:manage";

/**
 * The object a permission is asked about. Discriminated on `kind` so the
 * ownership rules inside `can()` can read the fields they need without casts.
 */
export type PermissionResource =
  | { readonly kind: "organization"; readonly orgId: OrgId }
  | { readonly kind: "billing"; readonly orgId: OrgId }
  | {
      readonly kind: "member";
      readonly orgId: OrgId;
      readonly memberId: MemberId;
      readonly targetUserId: UserId;
      readonly targetRole: Role;
    }
  | {
      readonly kind: "project";
      readonly orgId: OrgId;
      readonly projectId: ProjectId;
      readonly visibility: ProjectVisibility;
      readonly leadId: UserId | null;
    }
  | {
      readonly kind: "issue";
      readonly orgId: OrgId;
      readonly projectId: ProjectId;
      readonly issueId: IssueId;
      readonly authorId: UserId;
      readonly assigneeId: UserId | null;
    }
  | {
      readonly kind: "comment";
      readonly orgId: OrgId;
      readonly commentId: CommentId;
      readonly authorId: UserId;
    }
  | { readonly kind: "activity"; readonly orgId: OrgId }
  | { readonly kind: "notification"; readonly orgId: OrgId; readonly recipientId: UserId }
  | { readonly kind: "webhook"; readonly orgId: OrgId; readonly webhookId: WebhookId | null };

export type PermissionResourceKind = PermissionResource["kind"];

/** Verbose form of a decision, used by the settings UI to explain a denial. */
export interface PermissionDecision {
  readonly allowed: boolean;
  readonly action: PermissionAction;
  readonly resourceKind: PermissionResourceKind;
  readonly reason:
    | "granted_by_role"
    | "granted_by_ownership"
    | "granted_by_staff"
    | "denied_by_role"
    | "denied_cross_tenant"
    | "denied_unknown_action";
}

/**
 * In-app notification rows and unread counters.
 */
import { and, count, desc, eq, gte, inArray, isNull } from "drizzle-orm";
import { newId } from "@/lib/id";
import { getDb, notifications } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { orgPredicate } from "./base-repository";
import { compact, keysetPredicate, probeLimit, toPage } from "./_paging";
import { toNotification } from "./_mappers";
import type { ListNotificationsInput } from "@/schemas/notification";
import type {
  IsoTimestamp,
  NotificationId,
  OrgId,
  Page,
  UserId,
} from "@/types/common";
import type { Notification } from "@/types/notification";

type NewNotification = Omit<
  Notification,
  "id" | "createdAt" | "updatedAt" | "readAt"
>;

export async function listNotifications(
  input: ListNotificationsInput,
): Promise<Page<Notification>> {
  const db = getDb();
  const sort = { sortColumn: notifications.createdAt, idColumn: notifications.id };

  const filters = compact(
    orgPredicate(notifications.orgId, input.orgId),
    eq(notifications.recipientId, input.recipientId),
    input.unreadOnly ? isNull(notifications.readAt) : undefined,
    input.kind === undefined || input.kind.length === 0
      ? undefined
      : inArray(notifications.kind, [...input.kind]),
  );

  const total = db
    .select({ value: count() })
    .from(notifications)
    .where(and(...filters))
    .get();

  const rows = db
    .select()
    .from(notifications)
    .where(and(...filters, ...compact(keysetPredicate(sort, input.cursor))))
    .orderBy(desc(notifications.createdAt), desc(notifications.id))
    .limit(probeLimit(input.limit))
    .all();

  return toPage(rows, input.limit, total?.value ?? 0, toNotification, (row) => ({
    id: row.id,
    sortValue: row.createdAt,
  }));
}

/** Powers the bell badge, so it stays a single indexed count query. */
export async function countUnread(
  orgId: OrgId,
  recipientId: UserId,
): Promise<number> {
  const row = getDb()
    .select({ value: count() })
    .from(notifications)
    .where(
      and(
        orgPredicate(notifications.orgId, orgId),
        eq(notifications.recipientId, recipientId),
        isNull(notifications.readAt),
      ),
    )
    .get();
  return row?.value ?? 0;
}

export async function insertNotification(
  orgId: OrgId,
  input: NewNotification,
): Promise<Notification> {
  const inserted = await insertNotifications(orgId, [input]);
  const row = inserted.at(0);
  if (!row) throw new Error("Notification insert produced no row");
  return row;
}

/** Bulk insert used by the fan-out; one statement per recipient batch. */
export async function insertNotifications(
  orgId: OrgId,
  inputs: readonly NewNotification[],
): Promise<readonly Notification[]> {
  if (inputs.length === 0) return [];

  const stamp = toIsoTimestamp(new Date());
  const rows = getDb()
    .insert(notifications)
    .values(
      inputs.map((input) => ({
        id: newId(),
        orgId,
        recipientId: input.recipientId,
        kind: input.kind,
        title: input.title,
        body: input.body,
        href: input.href,
        actorId: input.actorId,
        readAt: null,
        channels: JSON.stringify(input.channels),
        createdAt: stamp,
        updatedAt: stamp,
      })),
    )
    .returning()
    .all();

  return rows.map(toNotification);
}

export async function markRead(
  orgId: OrgId,
  notificationId: NotificationId,
  at: IsoTimestamp,
): Promise<Notification> {
  const row = getDb()
    .update(notifications)
    .set({ readAt: at, updatedAt: at })
    .where(
      and(
        orgPredicate(notifications.orgId, orgId),
        eq(notifications.id, notificationId),
      ),
    )
    .returning()
    .get();

  if (!row) throw new Error(`Notification ${notificationId} not found`);
  return toNotification(row);
}

export async function markAllRead(
  orgId: OrgId,
  recipientId: UserId,
  at: IsoTimestamp,
): Promise<number> {
  // The recipient column only routes the bell; the inbox itself is the
  // organization's, so "all" means every unread row of the tenant.
  void recipientId;
  const rows = getDb()
    .update(notifications)
    .set({ readAt: at, updatedAt: at })
    .where(
      and(
        orgPredicate(notifications.orgId, orgId),
        isNull(notifications.readAt),
      ),
    )
    .returning({ id: notifications.id })
    .all();

  return rows.length;
}

/** The digest window query: everything still unread since `since`. */
export async function listUnreadSince(
  orgId: OrgId,
  recipientId: UserId,
  since: IsoTimestamp,
): Promise<readonly Notification[]> {
  const rows = getDb()
    .select()
    .from(notifications)
    .where(
      and(
        orgPredicate(notifications.orgId, orgId),
        eq(notifications.recipientId, recipientId),
        isNull(notifications.readAt),
        gte(notifications.createdAt, since),
      ),
    )
    .orderBy(desc(notifications.createdAt))
    .all();

  return rows.map(toNotification);
}

import { z } from "zod";
import type { NotificationKind } from "@/types/notification";
import {
  notificationIdSchema,
  orgIdSchema,
  pageRequestSchema,
  userIdSchema,
} from "./common";

export const notificationKindSchema = z.enum([
  "issue_assigned",
  "issue_status_changed",
  "issue_due_soon",
  "issue_overdue",
  "comment_created",
  "comment_mention",
  "member_invited",
  "member_joined",
  "project_archived",
  "plan_limit_reached",
  "digest_ready",
]);

export const notificationChannelSchema = z.enum(["in_app", "email", "webhook"]);

export const markNotificationReadSchema = z.object({
  orgId: orgIdSchema,
  notificationId: notificationIdSchema,
});

export const markAllNotificationsReadSchema = z.object({
  orgId: orgIdSchema,
});

export const listNotificationsSchema = z
  .object({
    orgId: orgIdSchema,
    recipientId: userIdSchema,
    unreadOnly: z.boolean().default(false),
    kind: z.array(notificationKindSchema).optional(),
  })
  .extend(pageRequestSchema.shape);

export const updateNotificationPreferenceSchema = z.object({
  orgId: orgIdSchema,
  userId: userIdSchema,
  kind: notificationKindSchema,
  inApp: z.boolean(),
  email: z.boolean(),
  digestOnly: z.boolean(),
});

const _kindParity: NotificationKind = "comment_mention" satisfies z.infer<
  typeof notificationKindSchema
>;
void _kindParity;

export type MarkNotificationReadInput = z.infer<
  typeof markNotificationReadSchema
>;
export type ListNotificationsInput = z.infer<typeof listNotificationsSchema>;
export type UpdateNotificationPreferenceInput = z.infer<
  typeof updateNotificationPreferenceSchema
>;

