/**
 * Resolves the one link every issue-related alert should carry, by walking
 * from the issue to its project and org slugs. Falls back to a dead-end path
 * only if the org or project has vanished since the event fired.
 */
async function issueHref(issue: Issue): Promise<string> {
  const [org, project] = await Promise.all([
    orgRepo.findOrgById(issue.orgId),
    projectRepo.findProjectById(issue.orgId, issue.projectId),
  ]);
  if (!org || !project) return `/issues/${issue.id}`;
  return issuePath(org.slug, project.slug, issue.number);
}

function registerFanOut(): void {
  if (registered) return;
  registered = true;

  // Being assigned at creation counts as an assignment, same as a later
  // reassignment — the recipient gets told exactly once either way.
  subscribe("issue.created", async (payload) => {
    if (payload.assigneeId === null) return;
    const issue = await issueRepo.findIssueById(payload.orgId, payload.issueId);
    if (!issue) return;
    await notify(payload.orgId, "issue_assigned", [payload.assigneeId], {
      title: "You were assigned an issue",
      body: `Issue ${issue.title} is now yours`,
      href: await issueHref(issue),
      actorId: payload.actorId,
    });
  });

  subscribe("issue.assigned", async (payload) => {
    const issue = await issueRepo.findIssueById(payload.orgId, payload.issueId);
    if (!issue) return;
    await notify(payload.orgId, "issue_assigned", [payload.assigneeId], {
      title: "You were assigned an issue",
      body: `Issue ${issue.title} is now yours`,
      href: await issueHref(issue),
      actorId: payload.actorId,
    });
  });

  // Covers the board drag-and-drop too, since `moveIssue` is a status change
  // under the hood. Nobody is told about their own change, and an unassigned
  // issue has nobody to tell.
  subscribe("issue.status_changed", async (payload) => {
    const issue = await issueRepo.findIssueById(payload.orgId, payload.issueId);
    if (!issue || issue.assigneeId === null) return;
    await notify(payload.orgId, "issue_status_changed", [issue.assigneeId], {
      title: "Issue status changed",
      body: `Issue ${issue.title} moved from ${payload.from} to ${payload.to}`,
      href: await issueHref(issue),
      actorId: payload.actorId,
    });
  });

  subscribe("issue.overdue", async (payload) => {
    if (payload.assigneeId === null) return;
    const issue = await issueRepo.findIssueById(payload.orgId, payload.issueId);
    if (!issue) return;
    await notify(payload.orgId, "issue_overdue", [payload.assigneeId], {
      title: "An issue is overdue",
      body: `Issue ${issue.title} was due ${payload.dueAt}`,
      href: await issueHref(issue),
      actorId: null,
    });
  });

  subscribe("comment.created", async (payload) => {
    const issue = await issueRepo.findIssueById(payload.orgId, payload.issueId);
    if (!issue) return;

    const href = await issueHref(issue);
    const watchers = [issue.authorId, ...(issue.assigneeId ? [issue.assigneeId] : [])];

    await notify(payload.orgId, "comment_created", watchers, {
      title: "New comment",
      body: `A comment was added to issue ${issue.title}`,
      href,
      actorId: payload.actorId,
    });

    if (payload.mentionedUserIds.length > 0) {
      await notify(
        payload.orgId,
        "comment_mention",
        payload.mentionedUserIds,
        {
          title: "You were mentioned",
          body: `You were mentioned on issue ${issue.title}`,
          href,
          actorId: payload.actorId,
        },
      );
    }
  });

  // The owner is the one who needs to know the workspace grew; the person
  // who joined already knows they joined.
  subscribe("member.joined", async (payload) => {
    const org = requireFound(
      await orgRepo.findOrgById(payload.orgId),
      "Organization",
      payload.orgId,
    );
    await notify(payload.orgId, "member_joined", [org.ownerId], {
      title: "A new member joined",
      body: `${payload.userId} joined ${org.name} as ${payload.role}`,
      href: settingsPath(org.slug, "members"),
      actorId: null,
    });
  });

  // Only a genuine refusal alerts the owner — the periodic recount's advance
  // warning (`refused: false`) never does. While one alert for a resource is
  // still unread, further refusals for that same resource add nothing.
  subscribe("billing.limit_exceeded", async (payload) => {
    if (!payload.refused) return;

    const org = await orgRepo.findOrgById(payload.orgId);
    if (!org) return;

    const alreadyUnread = await notificationRepo.hasUnreadMatching(
      payload.orgId,
      org.ownerId,
      "plan_limit_reached",
      payload.resource,
    );
    if (alreadyUnread) return;

    await notify(payload.orgId, "plan_limit_reached", [org.ownerId], {
      title: "Plan limit reached",
      body: `Your plan has no room for another ${payload.resource} (${payload.used}/${payload.limit} used)`,
      href: settingsPath(org.slug, "billing"),
      actorId: null,
    });
  });
}

registerFanOut();

