    const issue = await issueRepo.findIssueById(payload.orgId, payload.issueId);
    if (!issue) return;

    const href = await issueHref(issue);
    const watchers = [issue.authorId, ...(issue.assigneeId ? [issue.assigneeId] : [])];

    await notify(payload.orgId, "comment_created", watchers, {
      title: "New comment",
      body: `A comment was added to issue ${issue.title}`,
      href,
      actorId: payload.actorId,
    });

