/**
 * Walks from a search hit back to the page the app actually serves: issue and
 * comment hits both resolve to their issue's page, a project hit to its own.
 */
async function hrefFor(
  orgId: OrgId,
  orgSlug: string,
  row: Pick<SearchIndexRow, "subjectKind" | "subjectId">,
): Promise<string> {
  switch (row.subjectKind) {
    case "issue": {
      const issue = await issueRepo.findIssueById(
        orgId,
        row.subjectId as Issue["id"],
      );
      if (!issue) return `/${orgSlug}`;
      const project = await projectRepo.findProjectById(orgId, issue.projectId);
      if (!project) return `/${orgSlug}`;
      return issuePath(orgSlug, project.slug, issue.number);
    }
    case "comment": {
      const comment = await commentRepo.findCommentById(
        orgId,
        row.subjectId as Comment["id"],
      );
      if (!comment) return `/${orgSlug}`;
      const issue = await issueRepo.findIssueById(orgId, comment.issueId);
      if (!issue) return `/${orgSlug}`;
      const project = await projectRepo.findProjectById(orgId, issue.projectId);
      if (!project) return `/${orgSlug}`;
      return issuePath(orgSlug, project.slug, issue.number);
    }
    case "project": {
      const project = await projectRepo.findProjectById(
        orgId,
        row.subjectId as Project["id"],
      );
      if (!project) return `/${orgSlug}`;
      return projectPath(orgSlug, project.slug);
    }
  }
}

