import { afterAll, beforeAll, describe, expect, it } from "vitest";

import { emit } from "@/lib/event-bus";
import { can } from "@/lib/permissions";
import * as issueService from "@/server/services/issue-service";
import * as projectService from "@/server/services/project-service";
import {
  listNotifications,
  markAllRead,
  markRead,
} from "@/server/services/notification-service";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";

let cleanup: () => void;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});

afterAll(() => {
  cleanup();
});

describe("scratch verification", () => {
  it("denies reading another member's inbox even for an owner", async () => {
    const tenant = await createTenant("scratch-inbox", "growth");
    expect(
      can(tenant.actors.owner, "notification:read", {
        kind: "notification",
        orgId: tenant.org.id,
        recipientId: tenant.userIds.admin,
      }),
    ).toBe(false);
  });

  it("does not let markRead touch someone else's notification", async () => {
    const tenant: Tenant = await createTenant("scratch-markread", "growth");

    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, {
        title: "Scratch issue",
        assigneeId: tenant.userIds.admin,
      }),
    );
    void issue;

    const page = await listNotifications(tenant.actors.admin, {
      orgId: tenant.org.id,
      recipientId: tenant.userIds.admin,
      unreadOnly: false,
      limit: 25,
      cursor: null,
    });
    const target = page.items[0];
    expect(target).toBeDefined();
    if (!target) return;

    await expect(
      markRead(tenant.actors.viewer, {
        orgId: tenant.org.id,
        notificationId: target.id,
      }),
    ).rejects.toThrow();

    const after = await listNotifications(tenant.actors.admin, {
      orgId: tenant.org.id,
      recipientId: tenant.userIds.admin,
      unreadOnly: true,
      limit: 25,
      cursor: null,
    });
    expect(after.items.some((n) => n.id === target.id)).toBe(true);
  });

  it("markAllRead only clears the caller's own alerts", async () => {
    const tenant: Tenant = await createTenant("scratch-markall", "growth");

    await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, {
        title: "For admin",
        assigneeId: tenant.userIds.admin,
      }),
    );
    await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, {
        title: "For viewer",
        assigneeId: tenant.userIds.viewer,
      }),
    );

    await markAllRead(tenant.actors.admin, tenant.org.id);

    const adminUnread = await listNotifications(tenant.actors.admin, {
      orgId: tenant.org.id,
      recipientId: tenant.userIds.admin,
      unreadOnly: true,
      limit: 25,
      cursor: null,
    });
    const viewerUnread = await listNotifications(tenant.actors.viewer, {
      orgId: tenant.org.id,
      recipientId: tenant.userIds.viewer,
      unreadOnly: true,
      limit: 25,
      cursor: null,
    });

    expect(adminUnread.total).toBe(0);
    expect(viewerUnread.total).toBeGreaterThanOrEqual(1);
  });

  it("notifies the assignee when assigned at creation, with a working href", async () => {
    const tenant: Tenant = await createTenant("scratch-assign-create", "growth");

    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, {
        title: "Assigned at birth",
        assigneeId: tenant.userIds.admin,
      }),
    );

    const page = await listNotifications(tenant.actors.admin, {
      orgId: tenant.org.id,
      recipientId: tenant.userIds.admin,
      unreadOnly: false,
      kind: ["issue_assigned"],
      limit: 25,
      cursor: null,
    });

    expect(page.items.length).toBeGreaterThanOrEqual(1);
    const hit = page.items.find((n) => n.body.includes(issue.title));
    expect(hit).toBeDefined();
    expect(hit?.href).toBe(
      `/${tenant.org.slug}/projects/${tenant.project.slug}/issues/${issue.number}`,
    );
  });

  it("notifies the assignee when someone else changes issue status", async () => {
    const tenant: Tenant = await createTenant("scratch-status", "growth");

    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, {
        title: "Status flip",
        assigneeId: tenant.userIds.admin,
      }),
    );

    await issueService.changeIssueStatus(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      status: "in_progress",
    });

    const page = await listNotifications(tenant.actors.admin, {
      orgId: tenant.org.id,
      recipientId: tenant.userIds.admin,
      unreadOnly: false,
      kind: ["issue_status_changed"],
      limit: 25,
      cursor: null,
    });
    expect(page.items.length).toBe(1);

    // No notification for the member's own status change.
    await issueService.changeIssueStatus(tenant.actors.admin, {
      orgId: tenant.org.id,
      issueId: issue.id,
      status: "done",
    });
    const pageAfterSelf = await listNotifications(tenant.actors.admin, {
      orgId: tenant.org.id,
      recipientId: tenant.userIds.admin,
      unreadOnly: false,
      kind: ["issue_status_changed"],
      limit: 25,
      cursor: null,
    });
    expect(pageAfterSelf.items.length).toBe(1);
  });

  it("tells the owner when a member joins, not the member", async () => {
    const tenant: Tenant = await createTenant("scratch-member-joined", "growth");

    await emit("member.joined", {
      orgId: tenant.org.id,
      actorId: tenant.userIds.admin,
      occurredAt: new Date().toISOString() as never,
      memberId: "01HZZZMMMMMMMMMMMMMMMMMMMM" as never,
      userId: tenant.userIds.viewer,
      role: "member",
    });

    const ownerPage = await listNotifications(tenant.actors.owner, {
      orgId: tenant.org.id,
