    const tenant: Tenant = await createTenant("scratch-markread", "growth");

    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, {
        title: "Scratch issue",
        assigneeId: tenant.userIds.admin,
      }),
    );
    void issue;

    const page = await listNotifications(tenant.actors.admin, {
      orgId: tenant.org.id,
      recipientId: tenant.userIds.admin,
      unreadOnly: false,
      limit: 25,
      cursor: null,
    });
    const target = page.items[0];
    expect(target).toBeDefined();
    if (!target) return;

    await expect(
      markRead(tenant.actors.viewer, {
        orgId: tenant.org.id,
        notificationId: target.id,
      }),
    ).rejects.toThrow();

    const after = await listNotifications(tenant.actors.admin, {
      orgId: tenant.org.id,
      recipientId: tenant.userIds.admin,
      unreadOnly: true,
      limit: 25,
